export function selectInventoryForHydration(inventory, policy = {}) {
    const confirmed = stringSet(policy.selectedExternalIds);
    const canonical = stringSet(policy.canonicalExternalIds);
    const pinned = stringSet(policy.pinnedExternalIds);
    const hasConfirmedSelection = policy.selectedExternalIds !== undefined;
    const now = policy.now ?? new Date();
    const cutoff = new Date(now);
    cutoff.setUTCMonth(cutoff.getUTCMonth() - positiveInteger(policy.recentWindowMonths, 12));
    const selected = [];
    const deferred = [];
    const reasons = {};
    for (const item of inventory) {
        let reason;
        if (policy.hydrateAll)
            reason = "all";
        else if (confirmed.has(item.externalId))
            reason = "confirmed";
        else if (canonical.has(item.externalId) ||
            item.metadata?.canonical === true)
            reason = "canonical";
        else if (pinned.has(item.externalId) || item.metadata?.pinned === true)
            reason = "pinned";
        else if (!hasConfirmedSelection) {
            const modifiedAt = parsedDate(item.sourceModifiedAt);
            if (!modifiedAt)
                reason = "undated";
            else if (modifiedAt >= cutoff)
                reason = "recent";
        }
        if (reason) {
            selected.push(item);
            reasons[item.externalId] = reason;
        }
        else {
            deferred.push(item);
        }
    }
    return { selected, deferred, reasons };
}
function stringSet(values) {
    return new Set((values ?? []).map((value) => value.trim()).filter(Boolean));
}
function parsedDate(value) {
    if (!value)
        return null;
    const date = new Date(value);
    return Number.isNaN(date.getTime()) ? null : date;
}
function positiveInteger(value, fallback) {
    return Number.isInteger(value) && value > 0 ? value : fallback;
}
